const files = items
  .map((i) => i.json)
  .filter((f) => {
    const name = (f.name || '').toLowerCase();
    return name.endsWith('.mp3') || name.endsWith('.wav') || name.endsWith('.m4a');
  });

if (!files.length) {
  throw new Error('No music files found in Drive Music folder');
}

const pick = files[Math.floor(Math.random() * files.length)];

return [
  {
    json: {
      musicFileId: pick.id,
      musicName: pick.name,
      musicUrl: `https://drive.google.com/uc?export=download&id=${pick.id}`,
    },
  },
];

// CODE NODE: Prepare Render Body
// Connect: Select Random Music → Prepare Render Body → Create Render

const musicUrl = $('Select Random Music').item.json.musicUrl;
const videoUrl = $('Select Random Clip').item.json.videoUrl;

if (!musicUrl) throw new Error('No musicUrl');
if (!videoUrl) throw new Error('No videoUrl');

return [{
  json: {
    template_id: '0317527d-292d-45cb-944d-dbe35e8592b4',
    render_scale: 1,
    modifications: {
      'Video-1.source': videoUrl,
      'Video-1.volume': '0%',
      Hook: 'Fully Funded Scholarship',
      Script: 'Applications are open',
      CTA: 'Details in the Caption',
      'Voiceover.volume': '0%',
      'Music.source': musicUrl,
      'Music.volume': '45%',
    },
  },
}];

