const files = items
  .map((i) => i.json)
  .filter((f) => {
    const name = (f.name || '').toLowerCase();
    return name.endsWith('.mp3') || name.endsWith('.wav') || name.endsWith('.m4a');
  });

if (!files.length) {
  throw new Error('No music files found in Drive Music folder');
}

const pick = files[Math.floor(Math.random() * files.length)];

return [
  {
    json: {
      musicFileId: pick.id,
      musicName: pick.name,
      musicUrl: `https://drive.google.com/uc?export=download&id=${pick.id}`,
    },
  },
];

const musicUrl = $('Select Random Music1').item.json.musicUrl;
const videoUrl = $('Select Random Clip1').item.json.videoUrl;

if (!musicUrl) throw new Error('No musicUrl');
if (!videoUrl) throw new Error('No videoUrl');

let ai = $('AI Content1').item.json.output?.[0]?.content?.[0]?.text || $('AI Content1').item.json;
if (typeof ai === 'string') {
  try { ai = JSON.parse(ai); } catch (e) { ai = {}; }
}

const scenes = Array.isArray(ai.video_scenes) ? ai.video_scenes : [];
const sceneText = (n) => (scenes.find((s) => Number(s.scene) === n)?.text || '').toString().trim();
const hook = (ai.hook || sceneText(1) || ai.headline || 'Fully Funded Scholarship').toString().split('\n')[0].slice(0, 42);
const script = (ai.script || sceneText(2) || sceneText(3) || 'Applications are open').toString().split('\n')[0].slice(0, 36);
const cta = (ai.cta || 'Details in the Caption').toString();

return [{
  json: {
    template_id: '0317527d-292d-45cb-944d-dbe35e8592b4',
    render_scale: 1,
    modifications: {
      'Video-1.source': videoUrl,
      'Video-1.volume': '0%',
      Hook: hook,
      Script: script,
      CTA: cta,
      'Voiceover.volume': '0%',
      'Music.source': musicUrl,
      'Music.volume': '45%',
    },
  },
}];
